# -*- coding: utf-8 -*-
from odoo import models, fields, api

class HrExpense(models.Model):
    _name = 'hr.expense'
    _description = 'HR EXPENSE'
    _order = 'id desc'

    analytic_distribution = fields.Char(string="Analytic")
    analytic_distribution_search = fields.Char(string="Analytic Distribution Search")
    analytic_precision = fields.Integer(string="Analytic Precision")
    distribution_analytic_account_ids = fields.Many2many(comodel_name="account.analytic.account", string="Analytic Accounts", readonly=True)
    activity_ids = fields.One2many(comodel_name="mail.activity", inverse_name='parent_id', string="Activities")
    activity_state = fields.Selection(selection=[["overdue","Overdue"],["today","Today"],["planned","Planned"]], string="Activity State", readonly=True, help="Status based on activities\nOverdue: Due date is already passed\nToday: Activity date is today\nPlanned: Future activities.")
    activity_user_id = fields.Many2one(comodel_name="res.users", string="Responsible User")
    activity_type_id = fields.Many2one(comodel_name="mail.activity.type", string="Next Activity Type")
    activity_type_icon = fields.Char(string="Activity Type Icon", readonly=True, help="Font awesome icon e.g. fa-tasks")
    activity_date_deadline = fields.Date(string="Next Activity Deadline", readonly=True)
    my_activity_date_deadline = fields.Date(string="My Activity Deadline", readonly=True)
    activity_summary = fields.Char(string="Next Activity Summary")
    activity_exception_decoration = fields.Selection(selection=[["warning","Alert"],["danger","Error"]], string="Activity Exception Decoration", readonly=True, help="Type of the exception activity on record.")
    activity_exception_icon = fields.Char(string="Icon", readonly=True, help="Icon to indicate an exception activity.")
    activity_calendar_event_id = fields.Many2one(comodel_name="calendar.event", string="Next Activity Calendar Event", readonly=True)
    message_is_follower = fields.Boolean(string="Is Follower", readonly=True)
    message_follower_ids = fields.One2many(comodel_name="mail.followers", inverse_name='parent_id', string="Followers")
    message_partner_ids = fields.Many2many(comodel_name="res.partner", string="Followers (Partners)")
    message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Messages")
    has_message = fields.Boolean(string="Has Message", readonly=True)
    message_needaction = fields.Boolean(string="Action Needed", readonly=True, help="If checked, new messages require your attention.")
    message_needaction_counter = fields.Integer(string="Number of Actions", readonly=True, help="Number of messages requiring action")
    message_has_error = fields.Boolean(string="Message Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    message_has_error_counter = fields.Integer(string="Number of errors", readonly=True, help="Number of messages with delivery error")
    message_attachment_count = fields.Integer(string="Attachment Count", readonly=True)
    message_main_attachment_id = fields.Many2one(comodel_name="ir.attachment", string="Main Attachment")
    website_message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Website Messages", help="Website communication history")
    message_has_sms_error = fields.Boolean(string="SMS Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    name = fields.Char(string="Description", required=True)
    date = fields.Date(string="Expense Date")
    accounting_date = fields.Date(string="Invoice Date")
    employee_id = fields.Many2one(comodel_name="hr.employee", string="Employee", required=True)
    product_id = fields.Many2one(comodel_name="product.product", string="Fare")
    product_description = fields.Html(string="Product Description", readonly=True)
    product_uom_id = fields.Many2one(comodel_name="uom.uom", string="Unit of Measure", readonly=True)
    product_uom_category_id = fields.Many2one(comodel_name="uom.category", string="UoM Category", readonly=True, help="Conversion between Units of Measure can only occur if they belong to the same category. The conversion will be made based on the ratios.")
    unit_amount = fields.Float(string="Unit Price", required=True)
    unit_amount_display = fields.Float(string="Unit Price Display", readonly=True)
    quantity = fields.Float(string="Quantity", required=True)
    tax_ids = fields.Many2many(comodel_name="account.tax", string="Included taxes", help="Both price-included and price-excluded taxes will behave as price-included taxes for expenses.")
    amount_tax = fields.Monetary(string="Tax amount in Currency", readonly=True, help="Tax amount in currency")
    amount_tax_company = fields.Monetary(string="Tax amount", readonly=True, help="Tax amount in company currency")
    amount_residual = fields.Monetary(string="Amount Due", readonly=True)
    total_amount = fields.Monetary(string="Total In Currency")
    untaxed_amount = fields.Monetary(string="Total Untaxed Amount In Currency", readonly=True)
    company_currency_id = fields.Many2one(comodel_name="res.currency", string="Report Company Currency", readonly=True)
    total_amount_company = fields.Monetary(string="Total", readonly=True)
    company_id = fields.Many2one(comodel_name="res.company", string="Company", required=True, readonly=True)
    currency_id = fields.Many2one(comodel_name="res.currency", string="Currency", required=True)
    currency_rate = fields.Float(string="Currency Rate", readonly=True)
    account_id = fields.Many2one(comodel_name="account.account", string="Account", help="An expense account is expected")
    description = fields.Text(string="Internal Notes", readonly=True)
    payment_mode = fields.Selection(selection=[["own_account","Employee (to reimburse)"],["company_account","Company"],["3th","3th Party (Pay on Behalf)"]], string="Paid By")
    attachment_number = fields.Integer(string="Number of Attachments", readonly=True)
    attachment_ids = fields.One2many(comodel_name="ir.attachment", inverse_name='parent_id', string="Attachments")
    state = fields.Selection(selection=[["draft","To Submit"],["reported","Submitted"],["approved","Approved"],["done","Done"],["refused","Refused"]], string="Status", readonly=True)
    sheet_id = fields.Many2one(comodel_name="hr.expense.sheet", string="Expense Report", readonly=True)
    sheet_is_editable = fields.Boolean(string="Sheet Is Editable", readonly=True)
    approved_by = fields.Many2one(comodel_name="res.users", string="Approved By", readonly=True)
    approved_on = fields.Datetime(string="Approved On", readonly=True)
    reference = fields.Char(string="Bill Reference", help="Allow user to input bill reference. Paid by employee, expenses with the same vendor and reference will be created in the same invoice if they are on the same expense sheet.")
    is_refused = fields.Boolean(string="Explicitly Refused by manager or accountant", readonly=True)
    is_editable = fields.Boolean(string="Is Editable By Current User", readonly=True)
    is_ref_editable = fields.Boolean(string="Reference Is Editable By Current User", readonly=True)
    product_has_cost = fields.Boolean(string="Is product with non zero cost selected", readonly=True)
    product_has_tax = fields.Boolean(string="Whether tax is defined on a selected product", readonly=True)
    same_currency = fields.Boolean(string="Is currency_id different from the company_currency_id", readonly=True)
    duplicate_expense_ids = fields.Many2many(comodel_name="hr.expense", string="Duplicate Expense", readonly=True)
    sample = fields.Boolean(string="Sample")
    label_convert_rate = fields.Char(string="Label Convert Rate", readonly=True)
    vendor_id = fields.Many2one(comodel_name="res.partner", string="Vendor")
    to_invoice = fields.Boolean(string="Create Invoice", help="If checked, field Vendor is required, and this expense will be the input invoice")
    sea_buying_line_ids = fields.One2many(comodel_name="house.sea.buying.rate", inverse_name='parent_id', string="Buying Line")
    air_buying_line_ids = fields.One2many(comodel_name="house.air.buying.rate", inverse_name='parent_id', string="Buying Line")
    job_buying_line_ids = fields.One2many(comodel_name="job.buying.rate", inverse_name='parent_id', string="Buying Line")
    sea_pay_on_behalf_line_ids = fields.One2many(comodel_name="house.sea.pay.on.behalf.rate", inverse_name='parent_id', string="Buying Line")
    air_pay_on_behalf_line_ids = fields.One2many(comodel_name="house.air.pay.on.behalf.rate", inverse_name='parent_id', string="Buying Line")
    job_pay_on_behalf_line_ids = fields.One2many(comodel_name="job.pay.on.behalf.rate", inverse_name='parent_id', string="Buying Line")
    pay_for = fields.Many2one(comodel_name="res.partner", string="Pay For")
    job_id = fields.Many2one(comodel_name="freight.job", string="Job")
    service_job = fields.Selection(selection=[["air","Air"],["sea","Sea"],["truck","Truck"],["customs","Customs"],["other","Other"]], string="Service")
    house_id = fields.Many2one(comodel_name="freight.shipment.house", string="House")
    master_id = fields.Many2one(comodel_name="freight.shipment.master", string="Master")
    party_id = fields.Many2one(comodel_name="res.partner", string="3th Party")
    prepaid_by_id = fields.Many2one(comodel_name="res.partner", string="Prepaid By", readonly=True)
    can_add_to_job = fields.Boolean(string="Can Add To Job", readonly=True)
    charge_purpose = fields.Selection(selection=[["freight","Chi phí công ty"],["pay_on_behalf","Chi hộ trả hộ"],["container_deposit","Cược cont"]], string="Loại chi phí", required=True, help="Chi phí vận tải: cost của công ty.\nChi hộ trả hộ: chi hộ khách hàng (Pay On Behalf), bắt buộc chọn \"Chi cho\".\nCược cont: ký quỹ cược container cho hãng tàu/agent (không phải chi phí).")
    allowed_payment_mode = fields.Char(string="Allowed Payment Mode", readonly=True, help="Danh sách payment_mode hợp lệ (cho widget radio lọc option), phân tách bằng dấu phẩy.")
    customs_id = fields.Many2one(comodel_name="freight.customs.job", string="Customs")
    trucking_id = fields.Many2one(comodel_name="freight.truck.job", string="Trucking")
    plate_number = fields.Char(string="Plate Number", readonly=True)
    cds_number = fields.Char(string="CDs Number", readonly=True)
    customer_id = fields.Many2one(comodel_name="res.partner", string="Customer", readonly=True)
    user_id = fields.Many2one(comodel_name="res.users", string="Salesman", readonly=True)
    benefit_inf = fields.Char(string="Benefit Information")
    container = fields.Char(string="Container", readonly=True)
    vat_date = fields.Date(string="VAT Date")
    acc_date = fields.Date(string="Accounting Date")
    freight_distribute_house_ids = fields.Many2many(comodel_name="freight.shipment.house", string="Distributed Houses")
    untaxed_amount_company = fields.Monetary(string="Untaxed Amount (Company Currency)", readonly=True)
